-- The ingredient tree, part 2: the other shared ingredients the 2026-10-08 bar
-- seeds added. A name trigger filed 2,966 of them under a broad style ("Gin",
-- "Vermouth", "Rum") with no role and no check for duplicates: "Martini Rosso
-- Vermouth" sat under Vermouth, not Sweet Vermouth, beside our own Martini
-- Rosso. Part 1 (20261011100000) did the rows with no style at all.
--
-- Every fold and every bottle here was checked against a real source (the
-- producer, a major retailer, Difford's Guide or Wikipedia), not memory:
--   * 412 copies fold into a bottle or style we already have, each one
--     confirmed as the same product and expression (33 found by the bottle
--     check). Bacardi Spiced and Caribbean Spiced, Herradura Blanco and Plata
--     stay apart. Folded names stay as aliases.
--   * 416 rows take their proper label name, brand first; the old name
--     stays an alias.
--   * 2167 rows say what they are: 594 bottles, 1015 house preps,
--     558 styles.
--   * 1174 rows move from the broad style to the right one. A checked
--     bottle takes the style its source gives; a house prep or plain ingredient
--     only moves to a style under the one it had (Vermouth to Sweet Vermouth),
--     or anywhere when the classification was certain.
--   * New styles where needed: Horchata, Meringue, Tepache.
--
-- Left alone: bottles no source could find, names that could be several of a
-- brand's bottles ("Casamigos", "Hibiki", "Dolin Vermouth") and 338 names we
-- couldn't place. Matched by name key, so rows that don't exist here are
-- skipped; a second run changes nothing. Venue ingredients aren't touched.

SET "app.image_worker" = 'on';

-- No paid flavour jobs (same rule as 20261008900100): note the queue now and
-- put it back at the end. New styles change some drinks' flavour rules; that
-- refill runs separately, once it's OK'd.
CREATE TEMP TABLE "flavor_jobs_before" AS SELECT * FROM "private"."item_flavor_jobs";

CREATE TEMP TABLE generic_in (name text PRIMARY KEY, kind_of text);
INSERT INTO generic_in VALUES
($q$Horchata$q$, $q$Rice Milk$q$),
($q$Meringue$q$, $q$Egg$q$),
($q$Tepache$q$, $q$Pineapple$q$);

